"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import type React from "react";
import { useId, useLayoutEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_TEXT,
  type RulerAlignElementId,
  rulerAlignTimeline,
} from "./timeline";

const face = loadFont("normal", { weights: ["300"], subsets: ["latin"] });
const mono = loadMono("normal", { weights: ["400"], subsets: ["latin"] });

export interface RulerAlignProps {
  /** The line the ruler straightens. Letters without descenders sit best on the edge. */
  text?: string;
  /** The ruler's straight edge. */
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the line. Load it yourself; Geist by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Frames between letters as they fade in. */
  stagger?: number;
  /** Size of the line and ruler, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches single letters, the ruler's moves, the drops
   * and the taps, by the ids in `./timeline`. Frames on the scene timeline,
   * after `delay` and `speed`.
   */
  timing?: Timing<RulerAlignElementId>;
}

const THEMES = {
  dark: {
    bg: "#0A0A0A",
    fg: "#F2F2F0",
    rulerFill: "rgba(255,255,255,0.045)",
    rulerLine: "rgba(255,255,255,0.16)",
    tick: "rgba(255,255,255,0.34)",
    num: "rgba(255,255,255,0.42)",
  },
  light: {
    bg: "#FAFAF9",
    fg: "#0E0E0D",
    rulerFill: "rgba(0,0,0,0.03)",
    rulerLine: "rgba(0,0,0,0.14)",
    tick: "rgba(0,0,0,0.36)",
    num: "rgba(0,0,0,0.45)",
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_FALL = Easing.bezier(0.5, 0, 0.9, 0.6);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const LINE_HEIGHT = 1.2;
/** Gap between the baseline and the ruler while it waits underneath, in em. */
const PARK = 0.62;
const RULER_H = 0.46;

interface Layout {
  xs: number[];
  ws: number[];
  w: number;
  baseline: number;
}

/** Deterministic 0..1 noise. */
function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function sameLayout(a: Layout | null, b: Layout) {
  return (
    a !== null &&
    a.xs.join() === b.xs.join() &&
    a.w === b.w &&
    a.baseline === b.baseline
  );
}

/** A quick dip and recovery of the ruler over `len`, in em (positive is down). */
function tapDip(f: number, at: number, len: number) {
  const d = f - at;
  if (d < 0 || d > len) return 0;
  if (d < 3) return 0.05 * EASE_OUT(d / 3);
  return 0.05 * (1 - EASE_IN_OUT((d - 3) / (len - 3)));
}

/** The hop a letter makes when the ruler is tapped, in em (positive is up). */
function hop(f: number, at: number) {
  const d = f - at - 2;
  if (d < 0 || d > 10) return 0;
  return 0.07 * Math.sin((Math.PI * d) / 10);
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function RulerAlign(props: RulerAlignProps) {
  const {
    text = DEFAULT_TEXT,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = face.fontFamily,
    fontWeight = 300,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    rulerAlignTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const rulerEl = tl.get("ruler");
  const levelEl = tl.get("level");
  const riseEl = tl.get("rise");
  const taps = [tl.get("tap:0"), tl.get("tap:1")];
  const dips = (f: number) =>
    tapDip(f, taps[0].start, taps[0].length) +
    tapDip(f, taps[1].start, taps[1].length);
  const hops = (f: number) => hop(f, taps[0].start) + hop(f, taps[1].start);
  const t = THEMES[theme];
  const fg = ink ?? t.fg;
  const clipId = `ruler-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const em = Math.round(width * 0.088);
  const textStyle = {
    fontFamily,
    fontSize: em,
    fontWeight,
    letterSpacing: "-0.035em",
    lineHeight: LINE_HEIGHT,
    whiteSpace: "pre",
  } as const;

  const chars = Array.from(text);
  const rowRef = useRef<HTMLDivElement>(null);
  const baseRef = useRef<HTMLSpanElement>(null);
  const [layout, setLayout] = useState<Layout | null>(null);
  const [handle] = useState(() => delayRender("ruler-align: measuring"));
  const released = useRef(false);

  // biome-ignore lint/correctness/useExhaustiveDependencies: re-measure when the copy or size changes
  useLayoutEffect(() => {
    let live = true;
    Promise.all([
      face.waitUntilDone(),
      mono.waitUntilDone(),
      document.fonts.load(`${fontWeight} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => document.fonts.ready)
      .then(() => {
        if (!live) return;
        const row = rowRef.current;
        const base = baseRef.current;
        if (row && base) {
          const r = row.getBoundingClientRect();
          const scale = r.width / row.offsetWidth || 1;
          const spans = Array.from(row.querySelectorAll("[data-l]"));
          const next: Layout = {
            xs: spans.map(
              (el) => (el.getBoundingClientRect().left - r.left) / scale,
            ),
            ws: spans.map((el) => el.getBoundingClientRect().width / scale),
            w: row.offsetWidth,
            baseline: base.offsetTop,
          };
          setLayout((prev) => (sameLayout(prev, next) ? prev : next));
        }
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [text, em, handle, fontFamily, fontWeight]);

  const L = layout;
  const textW = L?.w ?? 0;
  const left = width / 2 - textW / 2;
  const baseY = height / 2 + em * 0.2;
  const rowTop = baseY - (L?.baseline ?? em);

  // The messy line: uneven gaps, letters off the baseline, a little tilt.
  // Neighbours alternate above and below so the line reads as jumbled.
  let cum = 0;
  const raw = chars.map((ch, i) => {
    const seed = i + 1;
    if (ch !== " ") cum += (hash(seed * 3.7) * 0.17 - 0.035) * em;
    const sign = i % 2 === 0 ? -1 : 1;
    return {
      off: cum,
      dy: sign * (0.07 + hash(seed * 7.3) * 0.13) * em,
      rot: (hash(seed * 5.9) - 0.5) * 14,
    };
  });
  const mean = raw.reduce((a, r) => a + r.off, 0) / Math.max(1, raw.length);
  const mess = raw.map((r) => ({ ...r, off: r.off - mean }));

  // Ruler motion.
  const rulerW = textW + em * 1.4;
  const rulerX0 = width / 2 - rulerW / 2;
  const inAt = (f: number) =>
    interpolate(f, [rulerEl.start, rulerEl.end], [0, 1], {
      ...clamp,
      easing: EASE_OUT,
    });
  const levelAt = (f: number) =>
    interpolate(f, [levelEl.start, levelEl.end], [0, 1], {
      ...clamp,
      easing: EASE_IN_OUT,
    });
  const inP = inAt(frame);
  const riseAt = (f: number) =>
    interpolate(f, [riseEl.start, riseEl.end], [0, 1], {
      ...clamp,
      easing: EASE_IN_OUT,
    });
  const tiltAt = (f: number) =>
    interpolate(inAt(f), [0, 1], [-5, -2.2]) * (1 - levelAt(f));
  const rulerTilt = tiltAt(frame);
  // The ruler is laid out where it rests, against the baseline, and travels
  // there by transform: layout rounds a box to whole pixels, so a ruler eased
  // by `top` steps along with its numbers.
  const rulerDx = (-rulerW - em - rulerX0) * (1 - inP);
  const rulerDrop = (f: number) => em * PARK * (1 - riseAt(f)) + dips(f) * em;
  const rulerDy = rulerDrop(frame);
  const rulerMoving =
    Math.abs(rulerDrop(frame + 1) - rulerDy) > 1e-3 ||
    Math.abs(rulerDy - rulerDrop(frame - 1)) > 1e-3 ||
    Math.abs(tiltAt(frame + 1) - rulerTilt) > 1e-6 ||
    Math.abs(rulerTilt - tiltAt(frame - 1)) > 1e-6;

  // Kerning: each tap moves the letters halfway home.
  const slideP = (i: number, tap: (typeof taps)[number], f = frame) =>
    interpolate(
      f,
      [
        tap.start + tap.beat("slide") + (i % 4),
        tap.start + tap.beat("slide") + (i % 4) + tap.beat("slideLen"),
      ],
      [0, 1],
      {
        ...clamp,
        easing: EASE_IN_OUT,
      },
    );

  /** Where letter `i` sits on frame `f`: lift, its own tilt and squash. */
  const pose = (i: number, f: number) => {
    const m = mess[i];
    const letter = tl.get(`letter:${i}`);
    const fade = interpolate(f, [letter.start, letter.end], [0, 1], {
      ...clamp,
      easing: EASE_OUT,
    });

    // Vertical: below the baseline is positive.
    let y = m.dy;
    let rot = m.rot;
    let sx = 1;
    let sy = 1;
    if (m.dy > 0) {
      // Low letter: the rising edge (PARK em below the baseline at first)
      // pushes it up and flattens it.
      const lift = Math.max(0, em * PARK * (1 - riseAt(f)));
      y = Math.min(m.dy, lift);
      rot = m.rot * (y / m.dy);
    } else {
      // High letter: drops onto the edge once it reaches the baseline.
      const drop = tl.get(`drop:${i}`);
      const p = interpolate(f, [drop.start, drop.end], [0, 1], {
        ...clamp,
        easing: EASE_FALL,
      });
      y = m.dy * (1 - p);
      rot = m.rot * (1 - p);
      const d = f - drop.end;
      if (d >= 0 && d < 7) {
        const b = Math.sin((Math.PI * d) / 7) * (1 - d / 9);
        sx = 1 + 0.025 * b;
        sy = 1 - 0.05 * b;
      }
    }
    y += dips(f) * em - hops(f) * em;
    return { fade, y: y + (1 - fade) * em * 0.12, rot, sx, sy };
  };

  const glyphs = chars.map((ch, i) => {
    if (ch === " ") return null;
    const m = mess[i];
    const w = L?.ws[i] ?? 0;
    const home = left + (L?.xs[i] ?? 0);
    const { fade, y, rot, sx, sy } = pose(i, frame);
    // The kerning slide is laid out where it ends and travels there by
    // transform: a letter handed from one layout `left` to the next jumps by
    // the rounding.
    const xOf = (k1: number, k2: number) =>
      home + m.off * (1 - 0.55 * k1 - 0.45 * k2);
    const xAt = (f: number) =>
      xOf(slideP(i, taps[0], f), slideP(i, taps[1], f));
    const xRest = xOf(1, 1);
    const x = xAt(frame);
    // Marked as moving while the letter travels or squashes.
    const near = (a: ReturnType<typeof pose>, b: ReturnType<typeof pose>) =>
      Math.abs(a.y - b.y) <= 1e-3 && Math.abs(a.sy - b.sy) <= 1e-6;
    const here = { fade, y, rot, sx, sy };
    const moving =
      !near(pose(i, frame + 1), here) ||
      !near(here, pose(i, frame - 1)) ||
      Math.abs(xAt(frame + 1) - x) > 1e-3 ||
      Math.abs(x - xAt(frame - 1)) > 1e-3;

    return (
      <span
        key={i}
        style={{
          ...textStyle,
          position: "absolute",
          left: xRest,
          top: rowTop,
          color: fg,
          opacity: fade,
          filter: fade < 1 ? `blur(${(1 - fade) * 8}px)` : undefined,
          transformOrigin: `${w / 2}px ${L?.baseline ?? em}px`,
          transform: `translate(${x - xRest}px, ${y}px) rotate(${rot}deg) scale(${sx}, ${sy})${glide(moving)}`,
        }}
      >
        {ch}
      </span>
    );
  });

  // Ruler ticks: a long one every 10 units, mid every 5.
  const unit = em * 0.06;
  const ticks: { x: number; h: number; n: number | null }[] = [];
  const count = Math.floor((rulerW - em * 0.2) / unit);
  for (let k = 0; k <= count; k++) {
    const long = k % 10 === 0;
    const mid = k % 5 === 0;
    ticks.push({
      x: em * 0.1 + k * unit,
      h: long ? 0.2 : mid ? 0.13 : 0.075,
      n: long ? k / 10 : null,
    });
  }

  const hair = Math.max(1.5, width / 720);

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent" ? undefined : (background ?? t.bg),
        overflow: "hidden",
      }}
    >
      {/* measuring row: never shown */}
      <div style={{ position: "absolute", visibility: "hidden", top: 0 }}>
        <div ref={rowRef} style={{ ...textStyle, display: "inline-block" }}>
          {chars.map((ch, i) => (
            <span key={i} data-l="">
              {ch}
            </span>
          ))}
          <span
            ref={baseRef}
            style={{ display: "inline-block", width: 0, height: 0 }}
          />
        </div>
      </div>

      <ScaleLayer scale={scale}>
        <div style={{ position: "absolute", inset: 0, opacity: L ? 1 : 0 }}>
          <div
            style={{
              position: "absolute",
              left: rulerX0,
              top: baseY,
              width: rulerW,
              height: em * RULER_H,
              transformOrigin: "50% 0%",
              transform: `translate(${rulerDx}px, ${rulerDy}px) rotate(${rulerTilt}deg)${glide(rulerMoving)}`,
              opacity: inP,
            }}
          >
            <svg
              width={rulerW}
              height={em * RULER_H}
              style={{ display: "block", overflow: "visible" }}
              aria-hidden
            >
              <defs>
                <clipPath id={clipId}>
                  <rect
                    x={0}
                    y={0}
                    width={rulerW}
                    height={em * RULER_H}
                    rx={em * 0.04}
                  />
                </clipPath>
              </defs>
              <rect
                x={0.5}
                y={0.5}
                width={rulerW - 1}
                height={em * RULER_H - 1}
                rx={em * 0.04}
                fill={t.rulerFill}
                stroke={t.rulerLine}
                strokeWidth={1}
              />
              <g clipPath={`url(#${clipId})`}>
                {ticks.map((tk) => (
                  <line
                    key={tk.x}
                    x1={tk.x}
                    x2={tk.x}
                    y1={0}
                    y2={tk.h * em}
                    stroke={t.tick}
                    strokeWidth={1}
                  />
                ))}
                {ticks.map((tk) =>
                  tk.n === null ? null : (
                    <text
                      key={`n${tk.x}`}
                      x={tk.x + em * 0.035}
                      y={em * 0.33}
                      fill={t.num}
                      fontFamily={mono.fontFamily}
                      fontSize={em * 0.095}
                    >
                      {tk.n}
                    </text>
                  ),
                )}
              </g>
              {/* the straight edge */}
              <rect x={0} y={0} width={rulerW} height={hair} fill={accent} />
            </svg>
          </div>

          {glyphs}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The messy line fading in letter by letter, the ruler sliding in tilted,
// levelling and rising to the baseline, the high letters dropping onto its
// edge, and two taps that kern the letters home. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

export type RulerAlignElementId =
  | `letter:${number}`
  | "ruler"
  | "level"
  | "rise"
  | `drop:${number}`
  | `tap:${number}`;

export interface RulerAlignTimingProps {
  text?: string;
  stagger?: number;
}

export const DEFAULT_TEXT = "Made to measure.";
export const IN_STAGGER = 2;
const IN = 0;
const FADE = 18;
const RULER_IN = 14;
const RULER_IN_LEN = 30;
const LEVEL = 44;
const LEVEL_LEN = 14;
const RISE = 56;
const RISE_LEN = 24;
const DROP = 82;
const DROP_STAGGER = 3;
const FALL = 10;
const TAPS = [112, 130];
const TAP_LEN = 10;
/** Letters start sliding this long into a tap, a frame apart in fours. */
const SLIDE_AT = 2;
const SLIDE_LEN = 16;

/** Letter `i` sits above the baseline in the messy line: it drops later. */
function isHigh(chars: string[], i: number) {
  return chars[i] !== " " && i % 2 === 0;
}

// `letter:<i>` is character `i` fading in (spaces have none); the letters
// form a chain. The ruler slides in, levels and rises (`ruler`, `level`,
// `rise`, a chain). `drop:<i>` is high letter `i` falling onto the edge;
// the drops follow the rise and each other. `tap:<k>` is a tap on the
// ruler: it dips over its length, and the letters slide from `slide` (plus
// a frame per letter, in fours) over `slideLen`. The taps follow the rise.
export const rulerAlignTimeline = defineTimeline<
  RulerAlignElementId,
  RulerAlignTimingProps
>(({ text = DEFAULT_TEXT, stagger = IN_STAGGER }) => {
  const chars = Array.from(text);
  const elements: TimelineElement<RulerAlignElementId>[] = [];
  let prevLetter: RulerAlignElementId | undefined;
  chars.forEach((ch, i) => {
    if (ch === " ") return;
    elements.push({
      id: `letter:${i}`,
      lane: "Letters",
      label: ch,
      start: IN + i * stagger,
      length: FADE,
      follows: prevLetter,
    });
    prevLetter = `letter:${i}`;
  });
  elements.push(
    {
      id: "ruler",
      lane: "Ruler",
      label: "slide in",
      start: RULER_IN,
      length: RULER_IN_LEN,
    },
    {
      id: "level",
      lane: "Ruler",
      label: "level",
      start: LEVEL,
      length: LEVEL_LEN,
      follows: "ruler",
    },
    {
      id: "rise",
      lane: "Ruler",
      label: "rise",
      start: RISE,
      length: RISE_LEN,
      follows: "level",
    },
  );
  let prevDrop: RulerAlignElementId = "rise";
  let k = 0;
  chars.forEach((ch, i) => {
    if (!isHigh(chars, i)) return;
    elements.push({
      id: `drop:${i}`,
      lane: "Drops",
      label: ch,
      start: DROP + k * DROP_STAGGER,
      length: FALL,
      follows: prevDrop,
    });
    prevDrop = `drop:${i}`;
    k++;
  });
  TAPS.forEach((at, n) => {
    elements.push({
      id: `tap:${n}`,
      lane: "Taps",
      label: `tap ${n + 1}`,
      start: at,
      length: TAP_LEN,
      follows: n > 0 ? `tap:${n - 1}` : "rise",
      beats: { slide: SLIDE_AT, slideLen: SLIDE_LEN },
    });
  });
  return elements.sort((a, b) => a.start - b.start);
});
